5. Handles SIGTERM gracefully within 3 seconds",
  "commands": [
    {
      "keystrokes": "cd /home/user/myproject && cat > subscribe.js << 'EOF'
#!/usr/bin/env node
'use strict';

const PocketBase = require('pocketbase').default || require('pocketbase');

function parseArgs(argv) {
  const args = { chat: null };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--chat') {
      args.chat = argv[i + 1];
      i++;
    } else if (a.startsWith('--chat=')) {
      args.chat = a.slice('--chat='.length);
    }
  }
  return args;
}

const args = parseArgs(process.argv.slice(2));
if (!args.chat) {
  process.stderr.write('Usage: node subscribe.js --chat <chatId>\n');
  process.exit(1);
}

const pb = new PocketBase('http://127.0.0.1:8090');
// Disable REDACTED-cancellation on errors so the connection stays alive.
pb.REDACTEDCancellation(false);

let unsubscribe = null;
let exiting = false;

function writeLine(obj) {
  try {
    const line = JSON.stringify(obj);
    process.stdout.write(line + '\n');
  } catch (e) {
    process.stderr.write('Failed to serialize event: ' + (e && e.message) + '\n');
  }
}

async function shutdown(signal) {
  if (exiting) return;
  exiting = true;
  process.stderr.write('Received ' + signal + ', shutting down\n');
  try {
    if (typeof pb.realtime.unsubscribe === 'function') {
      // Best-effort unsubscribe using the SDK's API.
      try { await pb.realtime.unsubscribe('messages'); } catch (e) { /* ignore */ }
    }
    if (typeof unsubscribe === 'function') {
      try { unsubscribe(); } catch (e) { /* ignore */ }
    }
    try { pb.realtime.disconnect(); } catch (e) { /* ignore */ }
  } finally {
    // Hard exit timer to satisfy the 3 second requirement.
    setTimeout(() => process.exit(0), 100).unref();
  }
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));
process.on('uncaughtException', (e) => {
  process.stderr.write('Uncaught exception: ' + (e && e.stack ? e.stack : e) + '\n');
});
process.on('unhandledRejection', (e) => {
  process.stderr.write('Unhandled rejection: ' + (e && e.stack ? e.stack : e) + '\n');
});

(async () => {
  try {
    await pb.admins.authWithPassword(process.env.PB_ADMIN_EMAIL, process.env.PB_ADMIN_PASSWORD);
  } catch (e) {
    process.stderr.write('Auth failed: ' + (e && e.message ? e.message : e) + '\n');
    process.exit(1);
  }

  // Escape single quotes for the filter expression.
  const safeChat = String(args.chat).replace(/'/g, "\\'");
  const filter = "chat='" + safeChat + "'";

  try {
    unsubscribe = await pb.collection('messages').subscribe('*', function (e) {
      // e has shape { action, record }
      if (!e) return;
      const record = e.record || {};
      writeLine({
        action: e.action,
        record: record,
      });
    }, { filter: filter });
  } catch (e) {
    process.stderr.write('Subscribe failed: ' + (e && e.message ? e.message : e) + '\n');
    process.exit(1);
  }

  process.stderr.write('Subscribed to messages with filter: ' + filter + '\n');
})();
EOF
